import type { NextConfig } from "next";

// The site is static HTML in public/site, generated by
// raw/site-revamp-2026-10-30/deep/build.py --prod (see README).
const PAGES: Record<string, string> = {
  "/": "index",
  "/outbound": "outbound",
  "/agents": "agents",
  "/free-list": "list",
  "/about": "about",
  "/call": "call",
  "/privacy": "privacy",
};

const nextConfig: NextConfig = {
  async rewrites() {
    return {
      beforeFiles: Object.entries(PAGES).map(([source, page]) => ({ source, destination: `/site/${page}.html` })),
      afterFiles: [],
      fallback: [],
    };
  },
  async headers() {
    return [
      {
        // Assets carry a content hash in the name, so they can be cached for good.
        source: "/site/:file([a-z-]+\\.[0-9a-f]{10}\\.(?:css|js|png))",
        headers: [{ key: "Cache-Control", value: "public, max-age=31536000, immutable" }],
      },
    ];
  },
  async redirects() {
    return [
      { source: "/ava", destination: "/agents", permanent: true },
      { source: "/sales-engineer", destination: "/agents", permanent: true },
      { source: "/what-we-build", destination: "/agents", permanent: true },
      // The old /work case studies were illustrative, never client results. They stay gone.
      { source: "/work", destination: "/agents", permanent: true },
      { source: "/work/:slug*", destination: "/agents", permanent: true },
      { source: "/kai", destination: "/", permanent: false },
      { source: "/nami", destination: "/", permanent: false },
      { source: "/pulse", destination: "/", permanent: true },
      { source: "/pilot", destination: "/", permanent: true },
      { source: "/okeanos", destination: "/", permanent: true },
      { source: "/revival-sprint", destination: "/", permanent: true },
      { source: "/managed-outbound", destination: "/outbound", permanent: true },
      // Decks and posts say /forecast; the page is the free list. Not permanent, in case the name changes back.
      { source: "/forecast", destination: "/free-list", permanent: false },
      { source: "/book", destination: "/call", permanent: false },
    ];
  },
};

export default nextConfig;
